arguments.command:
cd /tmp/c; python -m pip wheel --no-build-isolation --no-deps --no-index -q -w d2 . 2>&1|tail -3
python - <<'E'
import zipfile,glob
a=zipfile.ZipFile(glob.glob('dist/*.whl')[0]);b=zipfile.ZipFile(glob.glob('d2/*.whl')[0])
print(sorted(a.namelist())==sorted(b.namelist()))
for n in sorted(a.namelist()):print(n)
for n in a.namelist():
    if n.endswith(('METADATA','entry_points.txt')):print(a.read(n).decode()[:900])
E
tar tzf dist/*.tar.gz | grep -c "tests/\|docs/"; tar tzf dist/*.tar.gz | grep -i "timings\|csv"

